const { join, parse } = require('node:path')

module.exports = new class {
  async default4(name) {
    const file = join(__dirname, parse(name).name)
    try {
      return structuredClone(require(file))
    } catch (e) {
      throw new Error(`ENOENT: Could not load schema '${name}'`, { cause: e })
    }
  }
}
